-- 448: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 6 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_448_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_448_guard;
INSERT INTO _migration_448_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_026' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Taking π = 22/7, calculate the circumference of a circle of radius 7 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 22 cm","B. 44 cm","C. 154 cm","D. 88 cm"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Circumference = 2πr = 2 × (22/7) × 7 = 2 × 22 = 44 cm. (154 cm² is πr², the area, not the circumference.) Therefore the correct answer is B: 44 cm.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_026' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_448_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_027' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the area of a triangle with base 8 cm and height 9 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 72 cm²","B. 17 cm²","C. 36 cm²","D. 40 cm²"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Area of a triangle = ½ × base × height = ½ × 8 × 9 = 36 cm². (72 cm² forgets the ½, treating the triangle as a rectangle.) Therefore the correct answer is C: 36 cm².' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_027' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_448_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_028' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A cuboid has length 10 cm, width 6 cm and volume 240 cm³. Find its height.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 24 cm","B. 40 cm","C. 16 cm","D. 4 cm"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Volume = length × width × height, so height = volume ÷ (length × width) = 240 ÷ (10 × 6) = 240 ÷ 60 = 4 cm. Therefore the correct answer is D: 4 cm.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_028' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_448_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_029' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Taking π = 22/7, calculate the area of a circle of radius 14 cm.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 616 cm²","B. 88 cm²","C. 308 cm²","D. 1,232 cm²"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Area = πr² = (22/7) × 14² = (22/7) × 196 = 22 × 28 = 616 cm². (88 cm is the circumference 2πr, and 308 cm² uses r = 7 instead of r² = 14².) Therefore the correct answer is A: 616 cm².' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_029' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_448_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_030' AND NOT (q.topic_id IS 'topic_wassce_p2_math_men' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A cylinder has radius 7 cm and height 5 cm. Taking π = 22/7, calculate its volume.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 110 cm³","B. 770 cm³","C. 220 cm³","D. 1,540 cm³"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Volume = πr²h = (22/7) × 7² × 5 = 22 × 7 × 5 = 770 cm³. (220 cm² is 2πrh, the curved surface area, not the volume.) Therefore the correct answer is B: 770 cm³.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_030' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
